class Solution:
    def longestCommonSubpath(self, n: int, paths: List[List[int]]) -> int:
        def common(length):
            if length == 0:
                return True
            windows = set(tuple(paths[0][i:i + length])
                          for i in range(len(paths[0]) - length + 1))
            for p in paths[1:]:
                if len(p) < length:
                    return False
                nxt = set()
                for i in range(len(p) - length + 1):
                    w = tuple(p[i:i + length])
                    if w in windows:
                        nxt.add(w)
                windows = nxt
                if not windows:
                    return False
            return True

        lo, hi, ans = 1, min(len(p) for p in paths), 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if common(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

