class Solution {
public:
    int longestCommonSubpath(int n, vector<vector<int>>& paths) {
        auto common = [&](int len) {
            if (len == 0) return true;
            set<vector<int>> cur;
            for (int i = 0; i + len <= (int)paths[0].size(); ++i)
                cur.insert(vector<int>(paths[0].begin() + i,
                                       paths[0].begin() + i + len));
            for (int p = 1; p < (int)paths.size(); ++p) {
                if ((int)paths[p].size() < len) return false;
                set<vector<int>> nxt;
                for (int i = 0; i + len <= (int)paths[p].size(); ++i) {
                    vector<int> w(paths[p].begin() + i, paths[p].begin() + i + len);
                    if (cur.count(w)) nxt.insert(move(w));
                }
                cur = move(nxt);
                if (cur.empty()) return false;
            }
            return true;
        };
        int lo = 1, hi = INT_MAX, ans = 0;
        for (auto& p : paths) hi = min(hi, (int)p.size());
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (common(mid)) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }
};

