class Solution {
    public int longestCommonSubpath(int n, int[][] paths) {
        int lo = 1, hi = Integer.MAX_VALUE, ans = 0;
        for (int[] p : paths) hi = Math.min(hi, p.length);
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (common(paths, mid)) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }

    private boolean common(int[][] paths, int len) {
        Set<String> cur = new HashSet<>();
        for (int i = 0; i + len <= paths[0].length; ++i)
            cur.add(key(paths[0], i, len));
        for (int p = 1; p < paths.length; ++p) {
            if (paths[p].length < len) return false;
            Set<String> nxt = new HashSet<>();
            for (int i = 0; i + len <= paths[p].length; ++i) {
                String k = key(paths[p], i, len);
                if (cur.contains(k)) nxt.add(k);
            }
            cur = nxt;
            if (cur.isEmpty()) return false;
        }
        return true;
    }

    private String key(int[] p, int i, int len) {
        StringBuilder sb = new StringBuilder();
        for (int j = i; j < i + len; ++j) sb.append(p[j]).append(',');
        return sb.toString();
    }
}

