                h1 = (h1 * B1 + c) % M1
                h2 = (h2 * B2 + c) % M2
                if i >= length:
                    h1 = (h1 - path[i - length] * pw1) % M1
                    h2 = (h2 - path[i - length] * pw2) % M2
                if i >= length - 1:
                    out.add(h1 * M2 + h2)
            return out

        def common(length):
            inter = None
            for p in paths:
                if len(p) < length:
                    return False
                hs = hashes(p, length)
                inter = hs if inter is None else inter & hs
                if not inter:
                    return False
            return True

        lo, hi, ans = 1, min(len(p) for p in paths), 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if common(mid):
                ans = mid
                lo = mid + 1
