class Solution {
public:
    int longestCommonSubpath(int n, vector<vector<int>>& paths) {
        const long long M1 = 1000000007LL, M2 = 998244353LL;
        const long long B1 = 131, B2 = 137;
        auto power = [](long long b, long long e, long long m) {
            long long r = 1;
            b %= m;
            while (e > 0) {
                if (e & 1) r = r * b % m;
                b = b * b % m;
                e >>= 1;
            }
            return r;
        };
        auto hashes = [&](vector<int>& p, int len) {
            unordered_set<long long> s;
            long long pw1 = power(B1, len, M1), pw2 = power(B2, len, M2);
            long long h1 = 0, h2 = 0;
            for (int i = 0; i < (int)p.size(); ++i) {
                h1 = (h1 * B1 + p[i]) % M1;
                h2 = (h2 * B2 + p[i]) % M2;
                if (i >= len) {
                    h1 = ((h1 - p[i - len] * pw1) % M1 + M1) % M1;
                    h2 = ((h2 - p[i - len] * pw2) % M2 + M2) % M2;
                }
                if (i >= len - 1) s.insert(h1 * M2 + h2);
            }
            return s;
        };
        auto common = [&](int len) {
            bool first = true;
            unordered_set<long long> inter;
            for (auto& p : paths) {
                if ((int)p.size() < len) return false;
                unordered_set<long long> hs = hashes(p, len);
                if (first) {
                    inter = move(hs);
                    first = false;
                } else {
                    unordered_set<long long> nxt;
                    for (long long h : inter)
                        if (hs.count(h)) nxt.insert(h);
                    inter = move(nxt);
                }
                if (inter.empty()) return false;
            }
            return true;
        };
        int lo = 1, hi = INT_MAX, ans = 0;
        for (auto& p : paths) hi = min(hi, (int)p.size());
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (common(mid)) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }
};

