class Solution {
    private static final long M1 = 1_000_000_007L, M2 = 998_244_353L;
    private static final long B1 = 131L, B2 = 137L;

    public int longestCommonSubpath(int n, int[][] paths) {
        int lo = 1, hi = Integer.MAX_VALUE, ans = 0;
        for (int[] p : paths) hi = Math.min(hi, p.length);
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (common(paths, mid)) { ans = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        return ans;
    }

    private boolean common(int[][] paths, int len) {
        Set<Long> inter = null;
        for (int[] p : paths) {
            if (p.length < len) return false;
            Set<Long> hs = hashes(p, len);
            if (inter == null) inter = hs;
            else inter.retainAll(hs);
            if (inter.isEmpty()) return false;
        }
        return true;
    }

    private Set<Long> hashes(int[] p, int len) {
        Set<Long> s = new HashSet<>();
        long pw1 = 1, pw2 = 1;
        for (int i = 0; i < len; ++i) {
            pw1 = pw1 * B1 % M1;
            pw2 = pw2 * B2 % M2;
        }
        long h1 = 0, h2 = 0;
        for (int i = 0; i < p.length; ++i) {
            h1 = (h1 * B1 + p[i]) % M1;
            h2 = (h2 * B2 + p[i]) % M2;
            if (i >= len) {
                h1 = ((h1 - p[i - len] * pw1) % M1 + M1) % M1;
                h2 = ((h2 - p[i - len] * pw2) % M2 + M2) % M2;
            }
            if (i >= len - 1) s.add(h1 * M2 + h2);
        }
        return s;
    }
}

